    [Theory]
    [MemberData(nameof(PostGisTestData))]
    public void TestEwkbRead_LittleEndian_MatchesPostGis(string label, int srid, string isoWkbHex, string ewkbNdrHex, string ewkbXdrHex)
    {
        var geometry = WkbReader.Parse(Convert.FromHexString(ewkbNdrHex), srid: 999);

        Assert.NotNull(geometry);
        Assert.Equal(srid == 0 ? 999 : srid, geometry.Srid);
        Assert.Equal(isoWkbHex, Convert.ToHexString(geometry.AsWkb()!), ignoreCase: true);
    }

    [Theory]
    [MemberData(nameof(PostGisTestData))]
    public void TestEwkbRead_BigEndian_MatchesPostGis(string label, int srid, string isoWkbHex, string ewkbNdrHex, string ewkbXdrHex)
    {
        var geometry = WkbReader.Parse(Convert.FromHexString(ewkbXdrHex), srid: 0);

        Assert.NotNull(geometry);
        Assert.Equal(srid, geometry.Srid);
        Assert.Equal(isoWkbHex, Convert.ToHexString(geometry.AsWkb()!), ignoreCase: true);
    }

    [Theory]
    [MemberData(nameof(PostGisTestData))]
    public void TestEwkbWrite_MatchesPostGis(string label, int srid, string isoWkbHex, string ewkbNdrHex, string ewkbXdrHex)
    {
        var geometry = WkbReader.Parse(Convert.FromHexString(isoWkbHex), srid);

        Assert.NotNull(geometry);
        Assert.Equal(ewkbNdrHex, Convert.ToHexString(geometry.AsEwkb()!), ignoreCase: true);
    }

    [Fact]
    public void TestEwkbRoundTrip_GeometryOfPoint_KeepsSrid()
    {
        var geometry = Geometry<Point>.FromWkt("POLYGON ((51 35, 52 35, 52 36, 51 36, 51 35))", 4326);

        var roundTripped = Geometry<Point>.FromWkb(geometry.AsEwkb()!, srid: 0);

        Assert.Equal(4326, roundTripped.Srid);
        Assert.Equal(geometry.AsWkt(), roundTripped.AsWkt());
    }
}
